import java.util.Arrays;

// Déclaration et initialisation
int[] notes = {12, 15, 9, 18, 11};

// Accès par index
System.out.println(notes[0]); // 12
System.out.println(notes.length); // 5

// Parcours
for (int note : notes) {
    System.out.print(note + " ");
}

// Tri
Arrays.sort(notes);
System.out.println(Arrays.toString(notes)); // [9, 11, 12, 15, 18]
